def apply_correction(planet: str, meeus_lon: int, maya_day: int) -> int:
    """Apply integer correction to Meeus position. Pure integer, zero float."""
    if planet not in CORRECTIONS:
        return meeus_lon
    corr = CORRECTIONS[planet]
    idx = (maya_day - CORR_START) // CORR_STEP
    if idx < 0 or idx >= len(corr) - 1:
        return meeus_lon  # outside table range
    c0 = corr[idx]
    c1 = corr[idx + 1]
    frac_num = (maya_day - CORR_START) % CORR_STEP
    correction = c0 + ((c1 - c0) * frac_num) // CORR_STEP
    return (meeus_lon + correction) % FULL_CIRCLE
